from collections import deque

def comps_coords(grid, pred):
 H,W=len(grid),len(grid[0]); seen=set(); out=[]
 for r in range(H):
  for c in range(W):
   if (r,c) in seen or not pred(grid[r][c]): continue
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    p=q.pop(); comp.append(p)
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     nr,nc=p[0]+dr,p[1]+dc
     if 0<=nr<H and 0<=nc<W and (nr,nc) not in seen and pred(grid[nr][nc]): seen.add((nr,nc));q.append((nr,nc))
   out.append(comp)
 return out
